head.script:
scwin.onpageload = function() {
    var jsonData = [{
        "col1": "a1",
        "col2": "a1"
    }, {
        "col1": "a2",
        "col2": "a2"
    }, {
        "col1": "a3",
        "col2": "a3"
    }, {
        "col1": "a4",
        "col2": "a4"
    }, {
        "col1": "a5",
        "col2": "a5"
    }, {
        "col1": "a6",
        "col2": "a6"
    }];
    dataList1.setJSON(jsonData);
};
scwin.onpageunload = function() {};
scwin.checkLayout = function() {
    var topAtComplete = parseInt(((j) => j.length ? j : $('#mf_autoComplete1_gridViewItemTable'))($('#autoComplete1_gridViewItemTable')).css("top"));
    var heightAtComplete = parseInt(((j) => j.length ? j : $('#mf_autoComplete1_gridViewItemTable'))($('#autoComplete1_gridViewItemTable')).css("height"));
    var topBox = parseInt(((j) => j.length ? j : $('#mf_autoComplete1'))($('#autoComplete1')).css("top"));
    var widthAt = parseInt(((j) => j.length ? j : $('#mf_autoComplete1_gridViewItemTable'))($('#autoComplete1_gridViewItemTable')).css("width"));
    var widthBox = parseInt(((j) => j.length ? j : $('#mf_autoComplete1'))($('#autoComplete1')).css("width"));
    return Math.abs(heightAtComplete + topAtComplete - topBox) < 5 && Math.abs(widthBox - widthAt) < 10;
}
scwin.checkLayout2 = function() {
    var topAtComplete = parseInt(((j) => j.length ? j : $('#mf_sel1_gridViewItemTable'))($('#sel1_gridViewItemTable')).css("top"));
    var heightAtComplete = parseInt(((j) => j.length ? j : $('#mf_sel1_gridViewItemTable'))($('#sel1_gridViewItemTable')).css("height"));
    var topBox = parseInt(((j) => j.length ? j : $('#mf_sel1'))($('#sel1')).css("top"));
    var widthAt = parseInt(((j) => j.length ? j : $('#mf_sel1_gridViewItemTable'))($('#sel1_gridViewItemTable')).css("width"));
    var widthBox = parseInt(((j) => j.length ? j : $('#mf_sel1'))($('#sel1')).css("width"));
    return topBox >= (heightAtComplete + topAtComplete) && Math.abs(widthBox - widthAt) < 10;
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 03-Apr-2018
    //end
}
